describe('Archive and Restore Record', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should successfully restore an archived record', () => {
    // Verify initial state: no records are visible
    cy.get('[data-testid="no-records-message"]').should('be.visible');

    // Archive a record
    cy.get('[data-testid="record-item-1"]').click();
    cy.get('[data-testid="archive-button"]').click();
    cy.get('[data-testid="confirm-archive-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-archive-button"]').click();

    // Verify record is archived
    cy.get('[data-testid="archive-status-badge"]').should('contain', 'Archived');

    // Verify no records are visible
    cy.get('[data-testid="no-records-message"]').should('not.exist');

    // Restore the archived record
    cy.get('[data-testid="restore-button"]').click();
    cy.get('[data-testid="confirm-restore-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-restore-button"]').click();

    // Verify record is restored
    cy.get('[data-testid="record-item-1"]').should('be.visible');
    cy.get('[data-testid="restore-status-badge"]').should('contain', 'Restored');

    // Verify record details are displayed
    cy.get('[data-testid="record-title"]').should('contain', 'Sample Record');
    cy.get('[data-testid="record-description"]').should('contain', 'Sample Description');

    // Verify restore button is disabled
    cy.get('[data-testid="restore-button"]').should('be.disabled');
  });

  it('should not restore a record if it is already visible', () => {
    // Verify initial state: no records are visible
    cy.get('[data-testid="no-records-message"]').should('be.visible');

    // Archive a record
    cy.get('[data-testid="record-item-2"]').click();
    cy.get('[data-testid="archive-button"]').click();
    cy.get('[data-testid="confirm-archive-modal"]').should('be.visible');
    cy.get('[data-testid="confirm-archive-button"]').click();

    // Verify record is archived
    cy.get('[data-testid="archive-status-badge"]').should('contain', 'Archived');

    // Verify no records are visible
    cy.get('[data-testid="no-records-message"]').should('not.exist');

    // Attempt to restore the archived record
    cy.get('[data-testid="restore-button"]').click();

    // Verify restore button is disabled
    cy.get('[data-testid="restore-button"]').should('be.disabled');

    // Verify no error message is displayed
    cy.get('[data-testid="restore-error-message"]').should('not.exist');

    // Verify record remains archived
    cy.get('[data-testid="archive-status-badge"]').should('contain', 'Archived');
  });
});
